package db_test

//go:generate go run ../../../cmd/volt gen --sql .

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/Piechutowski/volt/gen/model"
	"github.com/Piechutowski/volt/internal/disk"
	"github.com/Piechutowski/volt/lang"
)

// TestGeneratedFilesCurrent regenerates the package from its .volt files
// through the path volt gen takes and proves the committed files are
// byte-identical, that no generated file is left over, and that the
// package checks and vets clean (spec §generation-contract-informative).
// On failure: go generate ./examples/voltmeter/db
func TestGeneratedFilesCurrent(t *testing.T) {
	root, err := lang.FindRoot(disk.Source{}, ".")
	if err != nil {
		t.Fatal(err)
	}
	pr, err := lang.LoadDirs(disk.Source{}, root, []string{"."}, nil)
	if err != nil {
		t.Fatal(err)
	}
	if diags := lang.Check(pr); len(diags) > 0 {
		t.Fatalf("check: %v", diags)
	}
	if diags := lang.Vet(pr); len(diags) > 0 {
		t.Errorf("vet: %v", diags)
	}
	pkg := pr.PackageAt(".")
	if pkg == nil || !pkg.HasSchema() {
		t.Fatal("db is not loaded as a data package")
	}
	files, err := model.Generate(pkg, model.Options{Source: "package " + pkg.Path, SQL: true})
	if err != nil {
		t.Fatal(err)
	}
	for name, want := range files {
		got, err := os.ReadFile(name)
		if err != nil || !bytes.Equal(got, want) {
			t.Errorf("%s drifted from the generator (%v); run go generate ./examples/voltmeter/db", name, err)
		}
	}
	written, err := filepath.Glob("volt_*")
	if err != nil {
		t.Fatal(err)
	}
	for _, name := range written {
		if _, ok := files[name]; !ok {
			t.Errorf("%s is no longer generated", name)
		}
	}
	for name, code := range files {
		if strings.HasSuffix(name, ".go") && !bytes.HasPrefix(code, []byte("// Code generated by volt gen")) {
			t.Errorf("%s lacks the generated marker", name)
		}
	}
}
